
.page-story {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-bottom: 30px;
}

.hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
}
.hero h1 {
  font-size: clamp(22px, 5.5vw, 30px);
}
.hero i {
  font-size: 0.8em;
}
.sub {
  font-family: var(--font-hand);
  font-size: 13px;
  color: var(--c-text-muted);
  rotate: -3deg;
}

/* 两列等高：行高由左侧固定比例的地图决定，右侧面板绝对定位填满并内部滚动 */
.layout {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 14px;
  align-items: stretch;
}
.side-wrap {
  position: relative;
  min-height: 0;
  rotate: 1deg;
}
.side-wrap > .clip {
  right: 14px;
  top: -22px;
}
.side {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(120, 90, 60, 0.45) transparent;
}
@media (max-width: 480px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .side {
    position: relative;
    inset: auto;
    max-height: 560px;
  }
}

.map-wrap {
  padding: 8px 8px 6px;
  rotate: -0.8deg;
}
.map {
  position: relative;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  background: #d9c7a8;
}
/* 画布与底图同比例（941×1670），居中裁切，图钉以底图坐标定位 */
.canvas {
  position: absolute;
  left: 0;
  width: 100%;
  aspect-ratio: 941 / 1670;
  top: -13%;
  background: center / 100% 100% no-repeat;
}
.compass {
  position: absolute;
  left: 6px;
  top: 6px;
}

.place,
.route {
  position: absolute;
  font-family: var(--font-title);
  color: var(--c-text);
  background: rgba(246, 238, 220, 0.92);
  box-shadow: 1px 2px 4px rgba(40, 28, 18, 0.3);
  white-space: nowrap;
  pointer-events: none;
}
.place {
  font-size: 15px;
  padding: 2px 10px;
}
.place.city {
  left: 40%;
  top: 15%;
  rotate: -4deg;
}
.place.town {
  left: 4%;
  top: 75%;
  rotate: -6deg;
}
.route {
  left: 46%;
  top: 52%;
  font-family: var(--font-hand);
  font-size: 12px;
  padding: 1px 6px;
  rotate: 14deg;
}
.route b {
  display: inline-block;
  margin-left: 3px;
  padding: 0 4px;
  font-family: var(--font-latin);
  font-size: 10px;
  color: #fff;
  background: #2f4f88;
  border-radius: 3px 3px 8px 8px;
}

.pin {
  position: absolute;
  translate: -50% -100%;
  display: flex;
  align-items: center;
  gap: 2px;
  background: transparent;
  border: none;
  animation: ym-float 2.8s ease-in-out infinite;
}
.pin.home {
  left: 36%;
  top: 67%;
}
.pin.uni {
  left: 70%;
  top: 31%;
  animation-delay: 0.9s;
}
.pin .head {
  font-size: 28px;
  color: #c0392b;
  filter: drop-shadow(0 3px 2px rgba(0, 0, 0, 0.35));
  transition: transform 0.2s ease;
}
.pin-label {
  font-family: var(--font-hand);
  font-size: 13px;
  font-weight: 700;
  background: rgba(250, 244, 230, 0.95);
  padding: 1px 7px;
  box-shadow: 1px 2px 3px rgba(40, 28, 18, 0.3);
}
.pin:hover .head {
  transform: scale(1.15);
}
.pin.on .head {
  color: var(--c-primary);
}
.pin.on .pin-label {
  background: var(--c-primary);
  color: var(--c-primary-ink);
}

.map-hint {
  margin-top: 4px;
  font-family: var(--font-hand);
  font-size: 12px;
  color: var(--c-text-muted);
  text-align: center;
}

.side {
  padding: 16px 12px 12px;
}
.side h2 {
  font-size: 18px;
  margin-bottom: 8px;
}
.side h2 i {
  font-size: 0.75em;
}
.thumb {
  background: #fbf8f1;
  padding: 5px;
  box-shadow: var(--shadow-paper);
  rotate: -1.5deg;
  margin-bottom: 8px;
}
.thumb img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}
.tag {
  font-family: var(--font-title);
  font-size: 17px;
  color: var(--c-danger);
}
.tag i {
  font-size: 0.85em;
}
.meta {
  font-family: var(--font-hand);
  font-size: 12.5px;
  color: var(--c-text-muted);
  margin-bottom: 8px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 10px;
}
.field > span {
  font-family: var(--font-hand);
  font-size: 13.5px;
  font-weight: 700;
}
.field small {
  align-self: flex-end;
  font-size: 11px;
  color: var(--c-text-muted);
}
.desc textarea {
  width: 100%;
  resize: vertical;
  font-family: var(--font-hand);
  font-size: 13px;
  line-height: 32px;
  padding: 0 6px 0 36px;
  border: 1px solid rgba(150, 125, 95, 0.4);
  background-color: #fbf7ec;
  background-position: 0 0, 0 0, 0 0;
  outline: none;
}

.pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.split-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 4px;
}
@media (max-width: 480px) {
  .split-2 {
    grid-template-columns: 1fr;
  }
}
.hint-line {
  font-family: var(--font-hand);
  font-size: 11px;
  color: var(--c-text-muted);
}
.friend-card {
  padding: 8px;
  margin-top: 4px;
  background: rgba(239, 226, 198, 0.35);
  border-radius: 3px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.friend-title {
  font-family: var(--font-hand);
  font-size: 12.5px;
  font-weight: 700;
}
.field.compact {
  margin-bottom: 0;
}
.custom-roomie {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}
.custom-roomie .row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.custom-roomie .mini {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.custom-roomie .mini > span {
  font-family: var(--font-hand);
  font-size: 12px;
  font-weight: 700;
}
.ym-line-input.short {
  width: 72px;
  align-self: flex-start;
}
.ym-sticker.small {
  padding: 5px 10px;
  font-size: 13px;
}

.actions {
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}
.ym-sticker.picked {
  background-color: #f6dc8a;
  border-color: var(--c-primary);
}

.mark {
  left: 2px;
  bottom: -6px;
  rotate: -10deg;
}
.leaf {
  right: -8px;
  bottom: -14px;
  rotate: 30deg;
}
