
.page-world {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.stain-a {
  left: -30px;
  bottom: 30px;
}

.hero {
  padding: 14px 18px 12px;
  rotate: 0.4deg;
  border-radius: 2px;
}
.hero h1 {
  font-size: clamp(24px, 6vw, 34px);
}
.sub {
  margin-top: 4px;
  text-align: right;
  font-family: var(--font-hand);
  color: var(--c-text-muted);
  font-size: 13px;
}

.layout {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 18px;
  align-items: start;
}
@media (max-width: 460px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.letter {
  padding: 18px 16px 26px 40px;
  rotate: -1.2deg;
  min-height: 260px;
}
.letter h2 {
  font-size: 20px;
  margin-bottom: 10px;
}
.typewriter {
  position: relative;
  z-index: 1;
  min-height: 9em;
  white-space: pre-wrap;
  font-family: var(--font-hand);
  font-size: 14.5px;
  line-height: 32px;
  color: #3a2c22;
}
.typewriter:not(.done)::after {
  content: '▌';
  color: var(--c-primary);
  animation: blink 1s step-end infinite;
}
@keyframes blink {
  50% {
    opacity: 0;
  }
}
.letter-mark {
  right: -10px;
  bottom: -18px;
  rotate: -12deg;
  opacity: 0.6;
}

.postcards {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.card {
  position: relative;
  width: min(100%, 250px);
  background: #fbf8f1;
  padding: 8px 8px 6px;
  box-shadow: var(--shadow-paper);
}
.card img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  filter: saturate(1.05) contrast(1.02);
}
.card .clip {
  right: 14px;
  top: -18px;
  rotate: 8deg;
}
.card figcaption {
  margin-top: 6px;
  font-family: var(--font-hand);
  font-size: 13px;
  letter-spacing: 0.06em;
}
.card figcaption b {
  font-family: var(--font-latin);
  letter-spacing: 0.12em;
}

.drive {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-hand);
  font-size: 13px;
  color: var(--c-text);
  rotate: -3deg;
}
.drive b {
  font-size: 17px;
}

.notes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
@media (max-width: 460px) {
  .notes {
    grid-template-columns: 1fr;
  }
}

.tag {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 10px 12px;
  font-family: var(--font-hand);
  font-size: 13.5px;
  line-height: 1.45;
  color: #fbf3e2;
  background-image: var(--img-grain);
  border-radius: 3px;
  box-shadow: var(--shadow-paper);
}
.tag i {
  font-size: 20px;
  opacity: 0.9;
}
.tag.green {
  background-color: #5f7650;
}
.tag.amber {
  background-color: #c79a4a;
  color: #3a2a1f;
}
.tag.coral {
  background-color: #a8513c;
}

.actions {
  display: flex;
  justify-content: center;
  padding-top: 4px;
}

.leaf {
  right: -6px;
  bottom: -14px;
  rotate: 22deg;
}
