
.desk {
  position: relative;
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  padding: 14px 10px 18px;
  border-radius: 6px;
  background-color: var(--c-surface-desk);
  background-image:
    var(--img-grain),
    repeating-linear-gradient(
      92deg,
      rgba(0, 0, 0, 0.1) 0 2px,
      transparent 2px 9px,
      rgba(255, 220, 170, 0.05) 9px 11px,
      transparent 11px 23px
    ),
    linear-gradient(180deg, #5a3a26, #3e2618);
  overflow: hidden;
}

.desk-photo {
  position: absolute;
  right: 6%;
  top: -18px;
  width: 150px;
  height: 92px;
  background: v-bind(deskPhoto) center / cover;
  border: 6px solid #f4eee2;
  border-bottom-width: 14px;
  rotate: 5deg;
  box-shadow: var(--shadow-paper);
  opacity: 0.95;
}

.desk-leaf {
  right: -14px;
  bottom: -10px;
  rotate: -28deg;
  z-index: 6;
}

.folder {
  position: relative;
  z-index: 2;
}

.tab {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin-left: 10px;
  padding: 7px 22px 6px 16px;
  background-color: var(--c-surface-folder);
  background-image: var(--img-grain);
  border-radius: 10px 18px 0 0;
  box-shadow: inset 0 1px 0 rgba(255, 240, 210, 0.4);
}
.tab .ym-title {
  font-size: 20px;
}
.tab small {
  font-family: var(--font-hand);
  color: var(--c-text-muted);
  font-size: 12px;
}

.folder-body {
  position: relative;
  border-radius: 0 8px 8px 8px;
  padding: 12px 12px 22px;
}
