
.page-profile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-bottom: 54px;
}

.hero h1 {
  font-size: clamp(22px, 5.5vw, 30px);
}
.hero i {
  font-size: 0.8em;
  color: var(--c-text);
}

.layout {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr;
  gap: 16px;
  align-items: start;
}
@media (max-width: 520px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.card {
  padding: 18px 16px 18px 40px;
  rotate: -0.8deg;
}
.card h2 {
  font-size: 22px;
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 2px solid rgba(70, 100, 150, 0.45);
}

.row {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  min-height: 32px;
  margin-bottom: 4px;
  flex-wrap: wrap;
}
.row.top {
  align-items: flex-start;
}
.row > span:first-child {
  flex: 0 0 auto;
  font-family: var(--font-hand);
  font-size: 15px;
  font-weight: 700;
  padding-bottom: 4px;
  min-width: 3.4em;
}
.row > .ym-line-input,
.row > .pills {
  flex: 1 1 140px;
}
.row.top > span:first-child {
  padding-top: 4px;
}
textarea.ym-line-input {
  resize: vertical;
  line-height: 1.6;
}

.short {
  width: 76px !important;
  flex: 0 0 auto !important;
}
.unit-wrap {
  display: inline-flex;
  align-items: flex-end;
  gap: 4px;
}
.unit {
  font-family: var(--font-latin);
  font-style: normal;
  font-size: 14px;
  color: var(--c-text-muted);
  padding-bottom: 4px;
}
.hint {
  font-family: var(--font-hand);
  font-size: 12px;
  color: var(--c-text-muted);
  padding-bottom: 5px;
}
.err {
  display: block;
  margin: -2px 0 4px 3.8em;
  color: var(--c-danger);
  font-size: 12px;
}

input[type='number']::-webkit-inner-spin-button {
  opacity: 0.4;
}

.pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.note {
  padding: 22px 14px 18px;
  background-color: var(--c-surface-note);
  background-image:
    var(--img-grain),
    linear-gradient(180deg, rgba(255, 255, 255, 0.2), transparent 30%),
    radial-gradient(ellipse at 90% 100%, rgba(170, 120, 40, 0.18), transparent 60%);
  rotate: 1.6deg;
  margin-top: 10px;
  box-shadow: 2px 6px 14px rgba(40, 28, 18, 0.25);
}
.note .clip {
  right: 18px;
  top: -24px;
}
.note h2 {
  font-size: 20px;
  margin-bottom: 10px;
}
.note-leaf {
  right: 6px;
  bottom: 4px;
  rotate: -15deg;
  opacity: 0.85;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 12px;
}
.field > span {
  font-family: var(--font-hand);
  font-size: 14px;
  font-weight: 700;
}
.field small {
  font-weight: normal;
  color: var(--c-text-muted);
}

.actions {
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  padding-top: 4px;
}

.ticket {
  position: absolute;
  left: -4px;
  bottom: -8px;
  display: flex;
  rotate: -8deg;
  font-family: var(--font-latin);
  color: #2f4f68;
  filter: drop-shadow(1px 3px 3px rgba(30, 20, 10, 0.3));
  pointer-events: none;
}
.t-main,
.t-stub {
  background-color: #e9e1cc;
  background-image: var(--img-grain);
}
.t-main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 14px;
  border: 1.5px solid rgba(47, 79, 104, 0.6);
  outline: 3px solid #e9e1cc;
  border-right: 2px dashed rgba(47, 79, 104, 0.5);
  line-height: 1.2;
}
.t-main b {
  font-size: 14px;
  letter-spacing: 0.12em;
}
.t-main small {
  font-size: 7px;
  letter-spacing: 0.1em;
}
.t-main span {
  font-size: 8px;
  margin-top: 2px;
}
.t-stub {
  writing-mode: vertical-rl;
  font-size: 9px;
  padding: 4px 3px;
  border: 1.5px solid rgba(47, 79, 104, 0.6);
  border-left: none;
}

.stain {
  left: 40%;
  bottom: -40px;
}
